{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isradipine, a lipophilic poorly water-soluble drug, had a mean systemic availability of 16.5% in healthy volunteers after oral administration, below the 20% threshold, supporting low oral bioavailability for similarly lipophilic, absorption- and first-pass-limited molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentazocine, a lipophilic drug with extensive first-pass metabolism, had an oral bioavailability of 18% in normal subjects, below the 20% threshold, supporting a low-F prediction for lipophilic molecules with poor systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Rigosertib, a poorly soluble drug, reached 34.8% absolute oral bioavailability in fasting patients, above the 20% threshold, showing that poor solubility alone does not always force low bioavailability; however, this is weakly transferable to the much larger, highly lipophilic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Nifedipine has about 45% oral bioavailability in humans, above the threshold, but it is a much smaller dihydropyridine with near-complete absorption, so this high-F evidence has low transferability to the large polyisoprenoid quinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low absolute oral bioavailability (<20%) for the query, a large lipophilic polyisoprenoid benzoquinone (CoQ10-type), based on poor aqueous solubility and absorption, with indirect support from lipophilic first-pass drugs such as isradipine (16.5%) and pentazocine (18%); high-F comparators are less transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in the provided records.",
    "No IV comparator or human pharmacokinetic data for the query itself.",
    "No formulation, dose, or fed/fasted condition specified for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

